:root{
  --y:#f5c200;--y2:#ffd93d;--y3:#b38f00;
  --bk:#0a0a08;--bk2:#111110;--bk3:#191917;
  --bd:#2a2a26;--tx:#f0ede0;--tx2:#8a8878;
  --red:#e53e3e;
  --mono:'IBM Plex Mono',monospace;--sans:'IBM Plex Sans',sans-serif;--display:'Bebas Neue',cursive;
}
*{margin:0;padding:0;box-sizing:border-box}
html{scroll-behavior:smooth}
body{font-family:var(--sans);background:var(--bk);color:var(--tx);overflow-x:hidden}
::-webkit-scrollbar{width:4px}::-webkit-scrollbar-thumb{background:var(--y)}

/* WARNING STRIPE TOP */
.warning-top{height:6px;background:repeating-linear-gradient(90deg,var(--y) 0,var(--y) 20px,var(--bk) 20px,var(--bk) 40px)}

/* NAV */
.nav{background:var(--bk2);border-bottom:2px solid var(--y);padding:0 40px;height:68px;
  display:flex;align-items:center;justify-content:space-between;position:sticky;top:6px;z-index:100}
.logo{display:flex;align-items:center;gap:12px;text-decoration:none}
.logo-icon{width:40px;height:40px;background:var(--y);display:flex;align-items:center;justify-content:center;font-size:20px}
.logo-text{font-family:var(--display);font-size:26px;letter-spacing:2px;color:var(--tx)}
.logo-text span{color:var(--y)}
.nav-links{display:flex;gap:0;align-items:center}
.nav-links a{font-family:var(--mono);font-size:11px;font-weight:500;letter-spacing:1px;color:var(--tx2);text-decoration:none;
  padding:8px 16px;border-right:1px solid var(--bd);transition:all .25s}
.nav-links a:hover{color:var(--y);background:rgba(245,194,0,.04)}
.nav-cta{display:inline-flex;align-items:center;gap:8px;padding:10px 20px;background:var(--y);color:var(--bk);
  font-family:var(--mono);font-size:11px;font-weight:600;letter-spacing:1px;text-transform:uppercase;text-decoration:none;
  transition:all .25s;border-left:none}
.nav-cta:hover{background:var(--y2)}

/* HERO */
.hero{min-height:90vh;display:grid;grid-template-columns:1fr 1fr;position:relative;overflow:hidden}
/* Left panel */
.hero-left{padding:80px 40px;background:var(--bk);position:relative;z-index:2;display:flex;flex-direction:column;justify-content:center;
  border-right:2px solid var(--y)}
/* Cross-hatch bg */
.hero-left::before{content:'';position:absolute;inset:0;z-index:0;opacity:.03;
  background-image:
    repeating-linear-gradient(0deg,var(--y) 0,var(--y) 1px,transparent 1px,transparent 32px),
    repeating-linear-gradient(90deg,var(--y) 0,var(--y) 1px,transparent 1px,transparent 32px)}

.hero-badge{display:inline-flex;align-items:center;gap:8px;padding:6px 14px;background:var(--y);color:var(--bk);
  font-family:var(--mono);font-size:10px;font-weight:600;letter-spacing:2px;text-transform:uppercase;margin-bottom:28px;
  animation:slideDown .5s ease both .1s;position:relative;z-index:1}
.hero-badge i{font-size:10px}

h1.htitle{font-family:var(--display);font-size:clamp(60px,9vw,120px);line-height:.9;letter-spacing:2px;
  margin-bottom:24px;animation:slideDown .5s ease both .2s;position:relative;z-index:1}
h1.htitle .yellow{color:var(--y)}
h1.htitle .small{font-size:60%;display:block;color:var(--tx2)}

.hero-desc{font-size:14px;color:var(--tx2);line-height:1.8;max-width:420px;margin-bottom:36px;font-weight:300;
  animation:slideDown .5s ease both .3s;position:relative;z-index:1;
  border-left:3px solid var(--y);padding-left:16px}

.hero-btns{display:flex;gap:12px;flex-wrap:wrap;animation:slideDown .5s ease both .4s;position:relative;z-index:1}
.btn-yellow{display:inline-flex;align-items:center;gap:10px;padding:14px 32px;background:var(--y);color:var(--bk);
  font-family:var(--mono);font-size:12px;font-weight:600;letter-spacing:1px;text-transform:uppercase;text-decoration:none;
  transition:all .3s}
.btn-yellow:hover{background:var(--y2);transform:translateY(-2px);box-shadow:0 6px 24px rgba(245,194,0,.25)}
.btn-bk{display:inline-flex;align-items:center;gap:10px;padding:13px 28px;background:transparent;color:var(--tx);
  font-family:var(--mono);font-size:12px;font-weight:500;letter-spacing:1px;text-transform:uppercase;text-decoration:none;
  border:1px solid var(--bd);transition:all .3s}
.btn-bk:hover{border-color:var(--y);color:var(--y)}

/* Hero right - industrial graphic */
.hero-right{background:var(--bk2);position:relative;overflow:hidden;display:flex;align-items:center;justify-content:center}
.hero-gear{font-size:clamp(200px,30vw,360px);opacity:.06;position:absolute;
  animation:spin 30s linear infinite;transform-origin:center}
.hero-right-content{position:relative;z-index:2;text-align:center}
.hero-tool{font-size:120px;animation:float 3s ease-in-out infinite;display:block}
.hero-addr{margin-top:24px;padding:16px 24px;background:var(--bk3);border:1px solid var(--bd);
  font-family:var(--mono);font-size:11px;color:var(--tx2);letter-spacing:1px;text-align:left}
.hero-addr strong{display:block;color:var(--y);font-size:12px;margin-bottom:4px}

.hero-specs{position:absolute;bottom:0;left:0;right:0;border-top:2px solid var(--y);display:flex}
.spec{flex:1;padding:20px 28px;border-right:1px solid var(--bd)}
.spec:last-child{border-right:none}
.spec .sk{font-family:var(--mono);font-size:10px;color:var(--tx2);letter-spacing:1.5px;text-transform:uppercase;margin-bottom:4px}
.spec .sv{font-family:var(--display);font-size:28px;letter-spacing:1px;color:var(--y)}

/* SERVICES */
.services{padding:80px 40px;position:relative;z-index:1}
.sec-header{margin-bottom:48px}
.sec-tag{font-family:var(--mono);font-size:10px;color:var(--y);letter-spacing:2px;text-transform:uppercase;margin-bottom:8px}
.sec-title{font-family:var(--display);font-size:clamp(36px,5vw,64px);letter-spacing:2px;line-height:1}
.sec-title .dim{color:var(--tx2)}
.srv-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:2px;background:var(--bd)}
.srv-card{background:var(--bk2);padding:40px 32px;position:relative;overflow:hidden;transition:background .3s}
.srv-card:hover{background:var(--bk3)}
.srv-card::after{content:'';position:absolute;top:0;left:0;right:0;height:3px;background:var(--y);
  transform:scaleX(0);transform-origin:left;transition:transform .4s}
.srv-card:hover::after{transform:scaleX(1)}
.srv-num{font-family:var(--display);font-size:80px;color:rgba(245,194,0,.07);line-height:1;position:absolute;top:20px;right:20px}
.srv-ico{font-size:36px;margin-bottom:20px;display:block}
.srv-name{font-family:var(--display);font-size:28px;letter-spacing:1px;margin-bottom:8px}
.srv-desc{font-size:13px;color:var(--tx2);line-height:1.7}

/* WHY */
.why{background:var(--bk2);border-top:2px solid var(--y);border-bottom:2px solid var(--y);padding:80px 40px}
.why-inner{display:grid;grid-template-columns:1fr 2fr;gap:60px;align-items:center}
.why-left-title{font-family:var(--display);font-size:clamp(48px,7vw,96px);letter-spacing:2px;line-height:.9}
.why-left-title .y{color:var(--y)}
.why-items{display:grid;grid-template-columns:1fr 1fr;gap:24px}
.why-item{padding:28px;background:var(--bk3);border:1px solid var(--bd);position:relative;
  transition:all .4s;cursor:default}
.why-item:hover{border-color:var(--y);transform:translateY(-3px)}
.why-item::before{content:'';position:absolute;bottom:0;left:0;width:0;height:2px;background:var(--y);transition:width .4s}
.why-item:hover::before{width:100%}
.why-ico{font-size:28px;margin-bottom:12px}
.why-name{font-family:var(--display);font-size:20px;letter-spacing:1px;margin-bottom:6px}
.why-desc{font-size:12px;color:var(--tx2);line-height:1.7}

/* CONTACT */
.contact{padding:80px 40px}
.contact-inner{display:grid;grid-template-columns:1fr 1fr;gap:60px;align-items:start}
.contact-left-title{font-family:var(--display);font-size:clamp(40px,5vw,72px);letter-spacing:2px;line-height:.9;margin-bottom:24px}
.contact-left-title .y{color:var(--y)}
.contact-desc{font-size:14px;color:var(--tx2);line-height:1.8;margin-bottom:32px;font-weight:300}
.citem{display:flex;align-items:center;gap:16px;padding:18px 20px;background:var(--bk2);border:1px solid var(--bd);
  margin-bottom:8px;text-decoration:none;color:var(--tx);transition:all .3s}
.citem:hover{border-color:var(--y);transform:translateX(6px)}
.citem-ico{width:38px;height:38px;background:rgba(245,194,0,.1);display:flex;align-items:center;justify-content:center;color:var(--y);font-size:15px}
.citem small{display:block;font-family:var(--mono);font-size:9px;letter-spacing:1.5px;text-transform:uppercase;color:var(--tx2);margin-bottom:2px}
.citem span{font-size:14px}
.contact-map{width:100%;aspect-ratio:4/3;background:var(--bk2);border:2px solid var(--y);
  display:flex;flex-direction:column;align-items:center;justify-content:center;gap:16px;
  font-family:var(--mono);font-size:12px;color:var(--tx2);text-decoration:none;transition:all .3s}
.contact-map:hover{background:rgba(245,194,0,.03)}
.contact-map .map-ico{font-size:64px;opacity:.2}
.contact-map-txt{font-family:var(--mono);font-size:11px;letter-spacing:1px;color:var(--y)}

/* FOOTER */
footer{background:var(--bk);border-top:2px solid var(--y)}
.ft-warning{height:6px;background:repeating-linear-gradient(90deg,var(--y) 0,var(--y) 20px,var(--bk) 20px,var(--bk) 40px)}
.ft-inner{padding:48px 40px;display:grid;grid-template-columns:2fr 1fr 1fr;gap:40px}
.ft-brand{font-family:var(--display);font-size:28px;letter-spacing:2px;margin-bottom:12px}
.ft-brand .y{color:var(--y)}
.ft-desc{font-size:12px;color:var(--tx2);line-height:1.7;font-family:var(--mono);margin-bottom:16px}
.ft-title{font-family:var(--mono);font-size:10px;font-weight:600;letter-spacing:2px;text-transform:uppercase;color:var(--y);margin-bottom:14px;border-bottom:1px solid var(--bd);padding-bottom:8px}
.ft-link{display:block;font-size:12px;color:var(--tx2);text-decoration:none;margin-bottom:7px;font-family:var(--mono);transition:color .3s}
.ft-link:hover{color:var(--y)}
.ft-bot{border-top:1px solid var(--bd);padding:20px 40px;display:flex;justify-content:space-between;align-items:center;
  font-family:var(--mono);font-size:10px;color:var(--tx2);letter-spacing:1px}
.ft-bot span{color:var(--y)}

/* WA */
.wa{position:fixed;bottom:28px;right:28px;z-index:200;width:56px;height:56px;
  background:#25D366;display:flex;align-items:center;justify-content:center;
  font-size:24px;color:#fff;text-decoration:none;border:2px solid #1da851;
  box-shadow:0 4px 20px rgba(37,211,102,.3);transition:all .3s}
.wa:hover{transform:scale(1.1)}

/* ANIMATIONS */
@keyframes slideDown{from{opacity:0;transform:translateY(-20px)}to{opacity:1;transform:translateY(0)}}
@keyframes float{0%,100%{transform:translateY(0)}50%{transform:translateY(-12px)}}
@keyframes spin{from{transform:rotate(0deg)}to{transform:rotate(360deg)}}
.reveal{opacity:0;transform:translateY(24px);transition:opacity .6s ease,transform .6s ease}
.reveal.vis{opacity:1;transform:translateY(0)}
.d1{transition-delay:.1s}.d2{transition-delay:.2s}.d3{transition-delay:.3s}

@media(max-width:900px){
  .nav{padding:0 20px}
  .hero{grid-template-columns:1fr;min-height:auto}
  .hero-left{padding:80px 20px 40px;border-right:none;border-bottom:2px solid var(--y)}
  .hero-right{min-height:220px}
  .hero-specs{position:static;flex-wrap:wrap}
  .spec{padding:14px 20px}
  .services,.why,.contact{padding:60px 20px}
  .srv-grid,.why-items,.contact-inner,.ft-inner{grid-template-columns:1fr}
  .why-inner{grid-template-columns:1fr;gap:32px}
  .ft-inner{padding:40px 20px}
  .ft-bot{flex-direction:column;gap:8px;padding:16px 20px}
}
